namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class sinaimg extends cloudStorage2 { var $host = 'sinaimg.cn'; var $cookies; public function init() { $this->cookies = $this->options->cloud_storage_sina_cookies; $this->silent_scanning = $this->options->cloud_storage_sina_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_sina_delete_attachment_after_synced; } public function rand_ip() { $ip_long = array( array( '607649792', '608174079' ), array( '1038614528', '1039007743' ), array( '1783627776', '1784676351' ), array( '2035023872', '2035154943' ), array( '2078801920', '2079064063' ), array( '-1950089216', '-1948778497' ), array( '-1425539072', '-1425014785' ), array( '-1236271104', '-1235419137' ), array( '-770113536', '-768606209' ), array( '-569376768', '-564133889' ) ); $rand_key = mt_rand( 0, 9 ); $ip = long2ip( mt_rand( $ip_long[ $rand_key ][ 0 ], $ip_long[ $rand_key ][ 1 ] ) ); return $ip; } public function curl($url, $params=array()){ $ip = "192.168.1.1"; $header = array( 'X-FORWARDED-FOR:' . $ip, 'CLIENT-IP:' . $ip ); if ( isset( $params[ "httpheader" ] ) ) { $header = array_merge( $header, $params[ "httpheader" ] ); } $referer = empty( $params[ "ref" ] ) ? $url : $params[ "ref" ]; $user_agent = empty( $params[ "ua" ] ) ? $_SERVER[ 'HTTP_USER_AGENT' ] : $params[ "ua" ]; $ch = curl_init(); curl_setopt($ch, CURLOPT_HEADER, 0); curl_setopt($ch, CURLOPT_URL,$url); curl_setopt($ch, CURLOPT_HTTPHEADER, $header ); curl_setopt($ch, CURLOPT_REFERER, "https://weibo.com/" ); curl_setopt($ch, CURLOPT_USERAGENT, $user_agent ); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 0); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0); if ( !empty( $params[ "fields" ] ) ) { curl_setopt( $ch, CURLOPT_POST, true ); curl_setopt( $ch, CURLOPT_POSTFIELDS, $params[ "fields" ] ); } if (curl_exec($ch) === false) do_action( 'qqworld-collector-log', $this->log_id, 'sinaimg failed, Curl error: ', curl_error($ch) ); $result = curl_exec($ch); curl_close($ch); return $result; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $url = false; $api = 'https://picupload.weibo.com/interface/pic_upload.php?ori=1&mime=image%2Fjpeg&data=base64&url=0&markpos=1&logo=&nick=0&marks=1&app=miniblog'; $allowedExts = array('gif', 'jpeg', 'jpg', 'png'); $temp = explode('.', basename($source_path)); $extension = end($temp); if (in_array($extension, $allowedExts)) { $data = array('pic1' => new \CURLFile($source_path)); $head = array($this->cookies); $params['ua'] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/89.0.4389.90 Safari/537.36"; $params['fields'] = $data; $params['httpheader'] = $head; $data = $this->curl($api, $params); $preg = preg_match('/({.*)/i', $data, $match); if ($preg) { $json_data = json_decode($match[1], true); $width = $json_data['data']['pics']['pic_1']['width']; $size = $json_data['data']['pics']['pic_1']['size']; $height = $json_data['data']['pics']['pic_1']['height']; if (isset($json_data['data']['pics']['pic_1']['pid']) && $json_data['data']['pics']['pic_1']['pid']) { $url = 'http://tva1.sinaimg.cn/large/'.$json_data['data']['pics']['pic_1']['pid'].'.jpg'; } else { do_action( 'qqworld-collector-log', $this->log_id, 'sinaimg failed: ', 'pid not found.' . "\n" . print_r($json_data, true) ); } } else { do_action( 'qqworld-collector-log', $this->log_id, 'sinaimg failed: ', 'json_data not work.' ); } } else { do_action( 'qqworld-collector-log', $this->log_id, 'sinaimg failed: ($extension)', 'extension not match. ('.$extension.')' ); } return $url; } public function add_could_storage_form($guid) { $this->accessed = $this->is_current && $this->cookies; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>